//! Native inert Range content copying preserves real source owners and units.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=root>Main</div><input id=neighbor value=seed></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://range-copy.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn range_native_cloning_inert_partial_ancestors_and_selected_native_children_preserve_structure(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var parsed=new DOMParser().parseFromString('<body><template id=t><b>A😀B</b><span data-note=seed>Middle</span><em>End</em><i>Outside</i></template></body>','text/html'),content=parsed.getElementById('t').content,r=content.ownerDocument.createRange();r.setStart(content.firstChild.firstChild,1);r.setEnd(content.childNodes[2].firstChild,2);var before=r.toString(),copy=r.cloneContents();if(copy.nodeType!==11||copy.ownerDocument!==content.ownerDocument||copy.textContent!=='😀BMiddleEn'||copy.childNodes.length!==3||copy.firstChild.nodeName!=='B'||copy.lastChild.nodeName!=='EM'||copy.childNodes[1].getAttribute('data-note')!=='seed'||copy.childNodes[1]===content.childNodes[1]||copy.firstChild.firstChild===r.startContainer||r.toString()!==before||r.startOffset!==1||r.endOffset!==2)throw 'actual inert partial ancestor copy and selection pruning';content.childNodes[1].setAttribute('data-note','Changed');content.childNodes[1].firstChild.data='Changed';if(copy.childNodes[1].getAttribute('data-note')!=='seed'||copy.textContent!=='😀BMiddleEn')throw 'native source aliases are independent after clone';
"#);}
#[test]
fn range_native_cloning_inert_exact_character_kinds_collapsed_fragments_and_doctype_errors(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),nodes=[owner.createTextNode('\uD800A\uDC00'),owner.createCDATASection('\uD800A\uDC00'),owner.createComment('\uD800A\uDC00'),owner.createProcessingInstruction('target','\uD800A\uDC00')];for(var node of nodes){var r=owner.createRange();r.setStart(node,1);r.setEnd(node,3);var copy=r.cloneContents();if(copy.ownerDocument!==owner||copy.childNodes.length!==1||copy.firstChild.nodeType!==node.nodeType||copy.firstChild.ownerDocument!==owner||copy.firstChild.nodeValue.length!==2||copy.firstChild.nodeValue.charCodeAt(0)!==65||copy.firstChild.nodeValue.charCodeAt(1)!==56320||copy.firstChild===node||node.nodeValue.length!==3||node.nodeType===7&&copy.firstChild.target!=='target')throw 'actual inert partial kind and raw UTF16 copy';r.collapse(true);copy=r.cloneContents();if(copy.ownerDocument!==owner||copy.firstChild!==null||!r.collapsed)throw 'collapsed native inert fragment owner';}
var doc=document.implementation.createHTMLDocument('Native'),whole=doc.createRange();whole.selectNodeContents(doc);var failed=false;try{whole.cloneContents();}catch(e){failed=e instanceof DOMException&&e.name==='HierarchyRequestError';}if(!failed||whole.startContainer!==doc||whole.startOffset||whole.endOffset!==2)throw 'selected genuine inert Doctype typed refusal before effects';whole.setStartAfter(doc.doctype);var safe=whole.cloneContents();if(safe.ownerDocument!==doc||safe.firstChild.nodeName!=='HTML'||safe.firstChild===doc.documentElement||safe.childNodes.length!==1)throw 'actual inert Document child clone after excluded Doctype';
"#);}
#[test]
fn range_native_cloning_inert_full_subtrees_templates_attributes_and_no_execution_authority(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var parsed=new DOMParser().parseFromString('<body><template id=t><section data-k=stored><span>Text</span><template><b>Nested</b></template><script>throw 1</script></section></template></body>','text/html'),source=parsed.getElementById('t').content,element=source.firstChild,inner=element.childNodes[1].content,owner=source.ownerDocument,r=owner.createRange();r.selectNode(element);var copy=r.cloneContents(),cloned=copy.firstChild,nested=cloned.childNodes[1].content;if(copy.ownerDocument!==owner||cloned.ownerDocument!==owner||cloned===element||cloned.getAttribute('data-k')!=='stored'||nested===inner||nested.ownerDocument!==inner.ownerDocument||nested.firstChild===inner.firstChild||nested.textContent!=='Nested'||cloned.lastChild.textContent!=='throw 1'||r.startContainer!==source||r.startOffset||r.endOffset!==1)throw 'full native inert subtree and separate template content clones';element.setAttribute('data-k','Changed');inner.firstChild.firstChild.data='Changed';if(cloned.getAttribute('data-k')!=='stored'||nested.textContent!=='Nested')throw 'independent nested native sources';
"#);assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.has_navigation_request());}
#[test]
fn range_native_cloning_inert_atomic_bundle_work_copy_storage_deadline_refusal_and_recovery(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var parsed=new DOMParser().parseFromString('<body><template id=t><b>Before</b><span>Middle</span><i>After</i></template></body>','text/html'),content=parsed.getElementById('t').content,r=content.ownerDocument.createRange();r.setStart(content.firstChild.firstChild,1);r.setEnd(content.lastChild.firstChild,2);");p.begin_job();let record=p.state.ranges[0];let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let before=(bridge.state.retained,bridge.state.inert_documents.backing_bytes(),bridge.inert_node_count(),bridge.doc.nodes.len(),bridge.state.dom_commits,bridge.state.ranges.len());let limit=bridge.state.retained_limit;match profile{0=>bridge.state.host_work=0,1=>bridge.state.copy_work=1,2=>bridge.state.retained_limit=bridge.state.retained+32,_=>{bridge.state.host_work=4096;bridge.state.execution_deadline=Some(Instant::now());}}assert!(bridge.clone_range_contents(record).is_err());assert_eq!((bridge.state.retained,bridge.state.inert_documents.backing_bytes(),bridge.inert_node_count(),bridge.doc.nodes.len(),bridge.state.dom_commits,bridge.state.ranges.len()),before);assert_eq!((bridge.state.ranges[0].start,bridge.state.ranges[0].end),(record.start,record.end));bridge.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"var copy=r.cloneContents();if(copy.textContent!=='eforeMiddleAf'||copy.ownerDocument!==content.ownerDocument||content.textContent!=='BeforeMiddleAfter')throw 'fresh actual inert clone bundle recovery';");}
}
